import pytest

from tasks_api import InMemoryTaskRepository, Tag, Task, TaskStatus, normalize_tags


def _make_task(id=1, title="Test"):
    return Task(id=id, title=title)


class TestInMemoryTaskRepository:
    def test_add_and_get(self, memory_repo):
        task = _make_task()
        memory_repo.add(task)
        assert memory_repo.get(1) is task

    def test_get_missing(self, memory_repo):
        assert memory_repo.get(999) is None

    def test_add_duplicate_raises(self, memory_repo):
        memory_repo.add(_make_task(1))
        with pytest.raises(ValueError, match="already exists"):
            memory_repo.add(_make_task(1))

    def test_list_empty(self, memory_repo):
        assert list(memory_repo.list()) == []

    def test_list_returns_all(self, memory_repo):
        memory_repo.add(_make_task(1))
        memory_repo.add(_make_task(2, "Two"))
        assert len(list(memory_repo.list())) == 2

    def test_update(self, memory_repo):
        task = _make_task()
        memory_repo.add(task)
        task.title = "Updated"
        memory_repo.update(task)
        assert memory_repo.get(1).title == "Updated"

    def test_update_missing_raises(self, memory_repo):
        with pytest.raises(KeyError):
            memory_repo.update(_make_task(999))

